#include <stdio.h>
typedef struct Axis6W4Row { unsigned int lane, phase, watermark; int delta; } Axis6W4Row;
typedef struct Axis6W4Agg { unsigned int phase[5], watermark[5]; int value[5]; } Axis6W4Agg;
static unsigned int mix4(unsigned int h, unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear4(Axis6W4Agg* a){ for(int i=0;i<5;++i){ a->phase[i]=0u; a->watermark[i]=0u; a->value[i]=0; } }
static void absorb4(Axis6W4Agg* a,const Axis6W4Row* r){ unsigned int lane=r->lane%5u; if(r->phase<a->phase[lane]) return; if(r->phase>a->phase[lane]){ a->phase[lane]=r->phase; a->watermark[lane]=r->watermark; a->value[lane]=r->delta; return;} if(r->watermark>a->watermark[lane]){ a->watermark[lane]=r->watermark; a->value[lane]=r->delta; } else if(r->watermark==a->watermark[lane]) a->value[lane]+=r->delta; }
static unsigned int sig4(const Axis6W4Agg* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<5u; ++lane){ h=mix4(h,lane+1u); h=mix4(h,a->phase[lane]); h=mix4(h,a->watermark[lane]); h=mix4(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const Axis6W4Row rows[]={{0u,2u,1u,4},{1u,3u,2u,5},{2u,1u,3u,7},{3u,2u,4u,3},{4u,1u,2u,6},{0u,5u,2u,6},{1u,4u,3u,-1},{2u,5u,2u,8},{3u,4u,5u,2},{4u,5u,3u,4},{0u,5u,2u,-2},{1u,4u,3u,4},{2u,5u,4u,1},{3u,4u,5u,-3},{4u,5u,3u,-1},{0u,6u,4u,5},{1u,6u,5u,3},{2u,6u,4u,6},{3u,6u,6u,1},{4u,6u,2u,2}}; Axis6W4Agg d,p; clear4(&d); for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i) absorb4(&d,&rows[i]); clear4(&p); for(unsigned int phase=1u;phase<=6u;++phase) for(unsigned int lane=0;lane<5u;++lane) for(unsigned int watermark=1u;watermark<=6u;++watermark){ int merged=0,saw=0; for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i){ if(rows[i].phase!=phase || rows[i].lane%5u!=lane || rows[i].watermark!=watermark) continue; merged+=rows[i].delta; saw=1; } if(saw){ Axis6W4Row row={lane,phase,watermark,merged}; absorb4(&p,&row); }} unsigned int sd=sig4(&d), sp=sig4(&p); printf("%u %u %u\n", sd, sp, (sd==sp)?1u:0u); return 0; }
